SELECT t0.code AS "Code",t0.amount AS "Amount" FROM (SELECT t1.code AS "code",t1.amount AS "amount",t1.from_z AS "from_z",t1.thru_z AS "thru_z" FROM org.rates AS t1 WHERE t1.amount > 0) AS t0 WHERE t0.from_z <= '2021-06-01' AND (t0.thru_z > '2021-06-01' OR t0.thru_z IS NULL) ORDER BY t0.code ASC NULLS FIRST
